# Code generated by Claude
# Runs the named tests ONE AT A TIME, each with its output in docs/reports/logs/<test>_<time>.log, and a line per test in docs/reports/logs/tail_<TAG>_summary.txt with the exit code, the last result line,
# the free memory and swap before and after and the peak swap (flagged if above 1 GB).
# usage (in a detached tmux session):  bash experiments/run_tail.sh TAG test1 test2 ...      (face_test and mpvi_text_test take their usual arguments; nav / stance variants as in run_tests.sh)
cd "$(dirname "$0")/.."
source .venv/bin/activate
export MUJOCO_GL=egl
TAG=$1; shift
LOGS=docs/reports/logs; mkdir -p $LOGS
SUM=$LOGS/tail_${TAG}_summary.txt
for t in "$@"; do
  case "$t" in
    nav_core_test) args="--sim";;
    nav_follow_sim_test) args="--only on";;
    reach_map_restamp) args="--check";;
    *) args="";;
  esac
  log=$LOGS/${t}_$(date +%Y%m%d_%H%M%S).log
  before="$(free -m | awk 'NR==2{print "avail",$7,"MB"}'; free -m | awk 'NR==3{print "swap used",$3,"MB"}')"
  echo "=== $t start $(date +%T) | before: $before" >> $SUM
  ( while true; do free -m | awk 'NR==3{print $3}' >> /tmp/swap_$$.txt; sleep 5; done ) & mon=$!
  if [ "$t" = "safety_filter_model_check" ]; then python experiments/safety_filter_roundtrip.py --model-check > $log 2>&1; else python experiments/$t.py $args > $log 2>&1; fi
  code=$?
  kill $mon 2>/dev/null; peak=$(sort -n /tmp/swap_$$.txt | tail -1); rm -f /tmp/swap_$$.txt
  after="$(free -m | awk 'NR==2{print "avail",$7,"MB"}'; free -m | awk 'NR==3{print "swap used",$3,"MB"}')"
  flag=""; [ "${peak:-0}" -gt 1024 ] && flag=" *** SWAP ABOVE 1 GB ***"
  echo "=== $t exit $code at $(date +%T): $(grep -E 'checks passed|cases' $log | tail -1 | cut -c1-120) | after: $after | peak swap ${peak:-0} MB$flag | log $log" >> $SUM
done
echo TAIL_DONE >> $SUM
